const targetMap = new WeakMap();
let activeEffect = null;
const effectStack = [];
function track(t, k){ if(!activeEffect) return; let dm=targetMap.get(t); if(!dm) targetMap.set(t,(dm=new Map())); let dep=dm.get(k); if(!dep) dm.set(k,(dep=new Set())); dep.add(activeEffect); activeEffect.deps.add(dep); }
function trigger(t, k){ const dm=targetMap.get(t); if(!dm) return; const dep=dm.get(k); if(dep) [...dep].forEach(e=>e.run()); }
const ARR=["push","pop","shift","unshift","splice"];
function reactive(obj){
  if(obj===null || typeof obj!=='object') return obj;
  return new Proxy(obj, {
    get(t,k,r){ const res=Reflect.get(t,k,r);
      if(Array.isArray(t) && ARR.includes(k)) return function(...a){ const r=res.apply(t,a); trigger(t,'length'); return r; };
      track(t,k); return typeof res==='object' && res!==null ? reactive(res) : res; },
    set(t,k,v,r){ const old=t[k]; const res=Reflect.set(t,k,v,r); if(old!==v){ trigger(t,k); trigger(t,'length'); } return res; }
  });
}
function effect(fn){ const e={ deps:new Set(), run(){ e.deps.forEach(d=>d.delete(e)); e.deps.clear(); effectStack.push(e); activeEffect=e; try{ return fn(); } finally { effectStack.pop(); activeEffect=effectStack[effectStack.length-1]||null; } } }; e.run(); return e; }

